      "tipo": "GC",
      "causa_raiz": "Alocação massiva de memória transitória a cada frame no método Update via concatenação cumulativa de strings ('s += i.ToString()') e alocação desnecessária de arrays ('new object[10000]'), associada à execução de 'GameObject.FindObjectsOfType<GameObject>()', que além de varrer toda a árvore da cena, aloca um novo array gerenciado a cada iteração. Isso gerou mais de 2.6 MB de lixo por frame, forçando pausas longas de Garbage Collection (GC.Collect atingindo ~18 ms).",
      "codigo_refatorado": "using System;
using System.Collections.Generic;
using UnityEngine;

namespace PerformanceAdvisor.StressTest
{
    public class StressTestScene : MonoBehaviour
    {
        public bool stressGc = false;
        public bool stressCpu = false;
        public bool stressDraw = false;

        public GameObject testPrefab;

        [Range(1, 20)]
        public float spawnRadius = 10f;

        [Range(1, 50)]
        public int cubesPerFrame = 1;

        public bool useUniqueMaterials = false;

        [Range(1, 512)]
        public int cpuScansPerFrame = 1;

        public int emptyObjects = 0;
        public int gcConcatIterations = 1000;
        public int gcArrayAllocs = 0;
        public int overdrawLayers = 0;
        public Material overdrawMaterial;

        [Range(0, 2000)]
        public int prepopulateCount = 0;

        private static readonly MaterialPropertyBlock PropertyBlock = new MaterialPropertyBlock();
        private static readonly int ColorPropertyId = Shader.PropertyToID("_Color");
        private readonly List<GameObject> cachedGameObjects = new List<GameObject>(2048);

        private void Start()
        {
            if (prepopulateCount > 0 && testPrefab != null)
            {
                for (int i = 0; i < prepopulateCount; i++)
                {
                    SpawnOne();
                }
            }

            for (int i = 0; i < emptyObjects; i++)
            {
                new GameObject("Empty_" + i);
            }

            if (overdrawLayers > 0 && overdrawMaterial != null)
            {
                BuildOverdrawLayers();
            }
        }

        private void BuildOverdrawLayers()
        {
            Camera cam = Camera.main;
            if (cam == null) return;

            float halfFov = cam.fieldOfView * 0.5f * Mathf.Deg2Rad;
            for (int i = 0; i < overdrawLayers; i++)
            {
                float d = cam.nearClipPlane + 0.05f + i * 0.001f;
                float h = 2f * d * Mathf.Tan(halfFov) * 1.1f;
                var quad = GameObject.CreatePrimitive(PrimitiveType.Quad);
                Destroy(quad.GetComponent<Collider>());
                quad.name = "Overdraw_" + i;
                quad.transform.SetParent(cam.transform, false);
                quad.transform.localPosition = new Vector3(0f, 0f, d);
                quad.transform.localScale = new Vector3(h * cam.aspect, h, 1f);
                quad.GetComponent<Renderer>().sharedMaterial = overdrawMaterial;
            }
        }

        private void Update()
        {
            if (stressCpu)
            {
                cachedGameObjects.Clear();
                var activeScene = UnityEngine.SceneManagement.SceneManager.GetActiveScene();
                activeScene.GetRootGameObjects(cachedGameObjects);
            }

            if (stressDraw && testPrefab != null)
            {
                int n = Mathf.Max(1, cubesPerFrame);
                for (int i = 0; i < n; i++)
                {
                    SpawnOne();
                }
            }
        }

        private void SpawnOne()
        {
            var clone = Instantiate(
                testPrefab,
                UnityEngine.Random.insideUnitSphere * spawnRadius,
                Quaternion.identity);

            if (useUniqueMaterials)
            {
                var rend = clone.GetComponent<Renderer>();
                if (rend != null)
                {
                    PropertyBlock.SetColor(
                        ColorPropertyId,
                        new Color(UnityEngine.Random.value, UnityEngine.Random.value, UnityEngine.Random.value));
                    rend.SetPropertyBlock(PropertyBlock);
                }
            }
        }
    }
}",
      "explicacao_didatica": "O 'Garbage Collector' (GC) da Unity é o gari da memória: quando você cria objetos temporários no 'Update' (que roda dezenas de vezes por segundo), o chão se enche de lixo rapidamente. Fazer 's += i.ToString()' cria centenas de textos descartáveis instantaneamente, e chamar 'FindObjectsOfType' cria um array novinho toda vez. Quando a lixeira transborda, o jogo é obrigado a congelar (quase 18 milissegundos) para fazer a faxina. Na versão corrigida, removemos as alocações repetitivas do Update e usamos 'MaterialPropertyBlock' no lugar de 'renderer.material' (que duplica materiais e gera lixo e quebra de performance)."
    }
  ],
  "dicas_level_design": null
}

